      ped.fx = (ped.x - px) / (d || 1); ped.fz = (ped.z - pz) / (d || 1);
    }
  }
}

// ---- input handling (edge-triggered) ----
let tabDown = false, escDown = false, gDown = false, eDown = false, enterDown = false, fDown = false, cDown = false, mDown = false, pDown = false, rDown = false;
function handleKeys() {
