}

function frondTexture() {
  return canvasTex(128, 128, (g, w, h) => {
    g.clearRect(0, 0, w, h);
    g.strokeStyle = '#2f8f4e'; g.lineWidth = 7; g.lineCap = 'round';
    for (let i = 0; i < 7; i++) {
